def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 1:
            return float(min(budget, DAILY_SALARY * 0.85))
        return float(min(budget, DAILY_SALARY * 0.35))

    yesterday_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in alive_opponents:
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        if opp.get('budget', 0) >= budget:
            rich_opp += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev.get('bid', 0.0))

    slots = int(supply // WATER_REQ)
    if slots < 1:
        slots = 1

    my_urgent = hp <= 2 or no_water_days >= 1

    base = DAILY_SALARY * 0.42

    if slots >= 2:
        base = DAILY_SALARY * 0.34
    else:
        base = DAILY_SALARY * 0.78

    if my_urgent:
        base = max(base, DAILY_SALARY * 0.9)
    elif hp <= 4:
        base = max(base, DAILY_SALARY * 0.62)

    if urgent_opp > 0 and slots == 1:
        base = max(base, DAILY_SALARY * 0.88)
    elif urgent_opp > 0:
        base = max(base, DAILY_SALARY * 0.48)

    if rich_opp >= 2 and slots == 1:
        base = max(base, DAILY_SALARY * 0.92)

    if yesterday_bids:
        highest_prev = max(yesterday_bids)
        moderate_prev = 0.0
        for b in yesterday_bids:
            if b <= DAILY_SALARY * 1.05 and b > moderate_prev:
                moderate_prev = b

        if highest_prev >= 120:
            if my_urgent:
                base = max(base, DAILY_SALARY * 0.97)
            else:
                base = min(base, DAILY_SALARY * 0.5)
        elif highest_prev >= DAILY_SALARY * 0.85:
            if my_urgent or slots == 1:
                base = max(base, min(DAILY_SALARY * 0.96, highest_prev + 2.0))
            else:
                base = max(base, DAILY_SALARY * 0.52)
        elif moderate_prev > 0:
            target = moderate_prev + 1.5
            if slots >= 2 and not my_urgent:
                target = moderate_prev + 0.75
            base = max(base, target)

    reserve = 0.0
    if hp >= 6 and no_water_days == 0:
        reserve = DAILY_SALARY * 0.15
    elif hp >= 4:
        reserve = DAILY_SALARY * 0.08

    max_affordable = budget - reserve
    if my_urgent:
        max_affordable = budget

    if max_affordable < 0:
        max_affordable = 0.0

    bid = min(base, max_affordable)

    if my_urgent and bid < min(budget, DAILY_SALARY * 0.85):
        bid = min(budget, DAILY_SALARY * 0.85)

    if bid < 0:
        bid = 0.0

    return float(round(min(budget, bid), 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    # Alive opponents
    alive = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive.append(opp)

    if not alive:
        return min(my_status.get('budget', 0.0), DAILY_SALARY * 0.4)

    # Read yesterday bids and pressure signals
    yesterday_bids = []
    for opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                yesterday_bids.append(float(bid))
            except Exception:
                pass

    # Estimate how much water is likely available relative to our requirement
    # (Used only to scale bid aggressiveness; indices are not needed here.)
    supply_units = supply / float(WATER_REQ) if WATER_REQ else 0.0

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))

    # Determine aggressiveness from yesterday outcomes
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 0.0

    # If we expect strong competition (high bids yesterday), bid enough to avoid shortage.
    # If we are low HP, bid more.
    competition = 0.0
    if highest_prev_bid >= DAILY_SALARY * 1.2:
        competition = 1.0
    elif highest_prev_bid >= DAILY_SALARY * 0.8:
        competition = 0.7
    elif highest_prev_bid >= DAILY_SALARY * 0.4:
        competition = 0.4
    else:
        competition = 0.2

    hp_pressure = 0.0
    if my_hp <= 1.5:
        hp_pressure = 1.0
    elif my_hp <= 3.0:
        hp_pressure = 0.7
    elif my_hp <= 5.0:
        hp_pressure = 0.4
    else:
        hp_pressure = 0.2

    # Base bid targets: keep within budget and avoid overpaying.
    # When supply is tight (closer to MIN_SUPPLY), increase bids.
    tightness = 0.0
    if supply <= float(MIN_SUPPLY) + 0.5:
        tightness = 0.8
    elif supply <= float(MIN_SUPPLY) + 3.0:
        tightness = 0.5
    else:
        tightness = 0.25

    # Target bid heuristic
    # - If competition is high, anchor near avg/highest but cap at 0.95*budget.
    # - Otherwise, bid around 0.55*salary, adjusted by hp and tightness.
    if competition >= 0.7:
        target = max(avg_prev_bid, highest_prev_bid * 0.75)
        target *= (0.85 + 0.25 * hp_pressure + 0.15 * tightness)
    else:
        target = DAILY_SALARY * (0.45 + 0.35 * hp_pressure + 0.25 * tightness)

    # Additional scaling: if supply_units is low (<1.5), competition for full water is higher.
    if supply_units < 1.5:
        target *= 1.15

    # Final clamp
    max_affordable = my_budget
    if max_affordable <= 0:
        return 0.0

    bid = min(max_affordable, target)

    # Ensure we don't bid trivially when we still have budget and opponents likely bid for survival.
    min_reasonable = 0.15 * DAILY_SALARY
    if bid < min_reasonable and my_budget > min_reasonable:
        bid = min_reasonable

    # Also avoid bidding more than 95% of budget.
    bid = min(bid, 0.95 * my_budget)

    # Return as float
    return float(bid)
